window.kbPageData["views/entry/k-1affb1ac8e1f545e"] = {"key":"entry/k-1affb1ac8e1f545e","state":{"route":"entry/k-1affb1ac8e1f545e"},"node":{"id":"k-1affb1ac8e1f545e","mode":"k","title":"两期平均数的差值","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["两期平均数的差值等于现期平均数乘以总量增速与数量增速之差，再除以一加总量增速"],"qs":["国考 2025 行政执法 行测#126"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两期平均数的差值是现期平均数减去基期平均数。若平均数等于总量除以数量，总量和数量相对同一基期的增速分别为 a 和 b，则两期差值等于现期平均数乘以 (a−b)/(1+a)。","review":{"definition":"两期平均数的差值是现期平均数减去基期平均数。若平均数等于总量除以数量，总量和数量相对同一基期的增速分别为 a 和 b，则两期差值等于现期平均数乘以 (a−b)/(1+a)。","explanation":"将现期总量除以 1+a、现期数量除以 1+b，可还原基期的总量和数量。因此，基期平均数等于现期平均数乘以 (1+b)/(1+a)，用现期值减去基期值即可得到差值。第126题中，金额同比增长 6.97%，低于笔数的 12.59%，所以平均每笔金额下降。将万亿元除以亿笔后乘以 10000，得到现期平均每笔约 9382 元，再代入公式得差值约为 −493 元，对应 A 项“下降了不到1000元”。","references":[],"evidence":"支付系统共处理支付业务3358.88亿笔，金额3151.37万亿元，同比分别增长12.59%和6.97%。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 行测#126":{"paper":"国考 2025 行政执法 行测","n":126,"mod":"资料分析","src":["d8efe4e19862104d89c8.pdf",26],"asrc":["e2c4b1970d2b49eac0fd.pdf",41],"card":"fc799c4ddaa42a241c1de38b","links":[{"id":"k-1affb1ac8e1f545e","role":"解题依据","why":"总金额和笔数的同比增速可用于求出每笔金额的两期差值。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-1affb1ac8e1f545e":[["国考 2025 行政执法 行测#126"]]}};
